mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("[(1,2),(3,5),(6,7),(8,10),(12,16)]","1-2,3-10,12-16"),
        ("[(1,3),(9,10)]","1-3,4-8,9-10"),
        ("[(1,2),(9,10)]","1-2,4-8,9-10"),
        ("[(1,5),(9,11)]","1-8,9-11"),
        ("[(2,3),(5,6)]","2-3,4-8"),
        ("  \n[(1,2),(3,5),(6,7),(8,10),(12,16)]\n  ","1-2,3-10,12-16"),
        ("\n[(2,3),(5,6)]\n","2-3,4-8")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS insert-interval");
}
